// Block (composition) — a team member table with role metadata and row actions.
// Table and Menu own their behavior/look; this Block wires their collections.
import type { Ref } from "react";
import { Avatar } from "../components/Avatar";
import { Badge } from "../components/Badge";
import { Button } from "../components/Button";
import { Menu, MenuItem } from "../components/Menu";
import { Stack } from "../layouts/Stack";
import { ScrollArea } from "../components/ScrollArea";
import {
  Table,
  TableBody,
  TableCell,
  TableColumn,
  TableHeader,
  TableRow,
} from "../components/Table";
import "./MembersList.css";

export interface MembersListProps {
  members: {
    id: string;
    name: string;
    email: string;
    role: string;
    avatarSrc?: string;
  }[];
  onAction?: (id: string, action: string) => void;
  className?: string;
  /* The root is the ScrollArea (a div), not the Table — see the JSX. Note that `tsc` cannot
     police this: HTMLTableElement structurally satisfies HTMLDivElement, so the two are mutually
     assignable and a wrong element type here compiles clean. */
  ref?: Ref<HTMLDivElement>;
}

const columns = [
  { id: "member", label: "Member" },
  { id: "role", label: "Role" },
  { id: "actions", label: "Actions" },
];

const initials = (name: string) =>
  name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join("") || "U";

export function MembersList({ members, onAction, className, ref }: MembersListProps) {
  return (
    /* A `<table>` is `display: table`: it will not shrink below its min-content width and its own
       `overflow` cannot constrain it, so this Block spilled out of any region narrower than its
       columns — silently, since the box stays put and only the paint crosses. The scrollport is the
       root now, which is why it takes the Block class and the forwarded `ref`; the Table keeps its
       own look untouched (arrange, never re-style — block-contract.md §3). */
    <ScrollArea
      ref={ref}
      orientation="horizontal"
      className={className ? `sd-memberslist ${className}` : "sd-memberslist"}
    >
      <Table aria-label="Team members" className="sd-memberslist__table">
        <TableHeader columns={columns}>
          {(column) => (
            <TableColumn id={column.id} isRowHeader={column.id === "member"}>
              {column.label}
            </TableColumn>
          )}
        </TableHeader>
        <TableBody items={members} renderEmptyState={() => "No team members"}>
          {(member) => (
            <TableRow id={member.id} columns={columns}>
              {(column) => {
                if (column.id === "member") {
                  return (
                    <TableCell>
                      <Stack direction="row" align="center" gap="small" className="sd-memberslist__identity">
                        <Avatar src={member.avatarSrc} alt={member.name} size="small">
                          {initials(member.name)}
                        </Avatar>
                        <Stack gap="2x-small" className="sd-memberslist__details">
                          <span className="sd-memberslist__name sd-type-body-medium">
                            {member.name}
                          </span>
                          <span className="sd-memberslist__email sd-type-caption-medium">
                            {member.email}
                          </span>
                        </Stack>
                      </Stack>
                    </TableCell>
                  );
                }

                if (column.id === "role") {
                  return (
                    <TableCell>
                      <Badge>{member.role}</Badge>
                    </TableCell>
                  );
                }

                return (
                  <TableCell>
                    <Menu
                      aria-label={`Actions for ${member.name}`}
                      onAction={(key) => onAction?.(member.id, String(key))}
                      trigger={
                        <Button
                          variant="secondary"
                          size="small"
                          aria-label={`Open actions for ${member.name}`}
                        >
                          Actions
                        </Button>
                      }
                    >
                      <MenuItem id="change-role">Change role</MenuItem>
                      <MenuItem id="remove">Remove member</MenuItem>
                    </Menu>
                  </TableCell>
                );
              }}
            </TableRow>
          )}
        </TableBody>
      </Table>
    </ScrollArea>
  );
}

/* MembersList.css — .sd-memberslist (Block)
   Arrangement only: the team table fills its available region — and the root is the SCROLLPORT
   holding it (see the tsx), so it must be allowed to be narrower than the table: a flex/grid item
   defaults to `min-width: auto` and would grow back to the table's min-content width. */
.sd-memberslist {
  width: 100%;
  min-width: 0;
}

.sd-memberslist__table {
  width: 100%;
}

.sd-memberslist__email {
  color: var(--sd-color-text-muted);
}
